from collections import deque

def rotting_oranges(grid):
    """Return minimum minutes to rot all oranges, or -1 if impossible."""
    if not grid:
        return -1

    rows, cols = len(grid), len(grid[0])
    queue = deque()
    fresh_count = 0

    # Initialize: enqueue all rotten, count fresh
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == "R":
                queue.append((r, c))
            elif grid[r][c] == "F":
                fresh_count += 1

    # BFS level-by-level
    minutes = 0
    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    while queue and fresh_count > 0:
        minutes += 1
        # Process entire current level (all oranges that rotted this minute)
        for _ in range(len(queue)):
            r, c = queue.popleft()
            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols and grid[nr][nc] == "F":
                    grid[nr][nc] = "R"
                    fresh_count -= 1
                    queue.append((nr, nc))

    return minutes if fresh_count == 0 else -1
